//! Parity with the PyTorch `pocket-tts` package. `fixtures/text_cases.json` is
//! generated by `fixtures/gen_text_fixtures.py`; see its header.

use std::path::Path;

use sayd_pocket::text::{prepare_text_prompt, split_into_best_sentences};
use sayd_pocket::tokenizer::Tokenizer;
use serde_json::Value;

const MAX_TOKENS: usize = 50;

fn fixtures() -> Vec<Value> {
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/text_cases.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn tokenizer() -> Tokenizer {
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/tokenizer.model");
    Tokenizer::load(&p).unwrap()
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect()
}

#[test]
fn tokenizer_matches_python_ids() {
    let tok = tokenizer();
    for c in fixtures() {
        let text = c["text"].as_str().unwrap();
        let want: Vec<i64> = c["ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|i| i.as_i64().unwrap())
            .collect();
        assert_eq!(tok.encode(text), want, "input {text:?}");
    }
}

#[test]
fn prepare_text_prompt_matches_package() {
    for c in fixtures() {
        if c["error"].as_bool().unwrap() {
            continue;
        }
        let text = c["text"].as_str().unwrap();
        let (prepared, frames) = prepare_text_prompt(text);
        assert_eq!(prepared, c["prepared"].as_str().unwrap(), "input {text:?}");
        assert_eq!(
            frames as u64,
            c["frames_after_eos_guess"].as_u64().unwrap(),
            "input {text:?}"
        );
    }
}

#[test]
fn split_matches_package() {
    let tok = tokenizer();
    for c in fixtures() {
        let text = c["text"].as_str().unwrap();
        assert_eq!(
            split_into_best_sentences(&tok, text, MAX_TOKENS),
            strings(&c["chunks"]),
            "input {text:?}"
        );
    }
}

#[test]
fn long_text_splits_only_at_sentence_or_word_boundaries() {
    let tok = tokenizer();
    let case = fixtures()
        .into_iter()
        .max_by_key(|c| c["text"].as_str().unwrap().len())
        .unwrap();
    let text = case["text"].as_str().unwrap();
    assert!(text.len() > 1400);
    let chunks = split_into_best_sentences(&tok, text, MAX_TOKENS);
    assert!(chunks.len() > 1);
    for chunk in &chunks {
        assert!(tok.encode(chunk).len() <= MAX_TOKENS, "{chunk:?}");
    }
    let got: Vec<&str> = chunks.iter().flat_map(|c| c.split_whitespace()).collect();
    let want: Vec<&str> = text.split_whitespace().collect();
    assert_eq!(got, want);
}
